1	//! [`RequestLedger`] — the account book of live requests, and the per-step
2	//! statement it ships on the step stream.
3	//!
4	//! One account per unanswered request. The driver opens it at
5	//! [`RequestLedger::register`]; exactly one terminal transition closes it
6	//! ([`RequestLedger::finish`], [`RequestLedger::fail`],
7	//! [`RequestLedger::reject`], [`RequestLedger::retire`], or
8	//! [`RequestLedger::defer_finish`]); accounts still open when the ledger
9	//! drops are written off as `Failed` terminals (engine teardown). Because
10	//! every open is a submit and every close is a terminal, "terminal exactly
11	//! once" and "nothing after the terminal" are enforced here: touching a
12	//! closed or unknown account panics at the offending scheduler call site.
13	//!
14	//! Token counts on terminals derive from the ledger's own tally
15	//! ([`RequestLedger::push_tokens`]), never from model-side arithmetic.
16	//!
17	//! Scheduler-facing methods are `pub`. Opening accounts and shipping the
18	//! statement ([`RequestLedger::register`], [`RequestLedger::commit_step`],
19	//! [`RequestLedger::fail_all`]) are `pub(crate)`: the driver owns the
20	//! cadence, and model crates cannot reach them.
21	
22	use std::collections::HashMap;
23	use std::sync::Arc;
24	use std::sync::atomic::AtomicBool;
25	use std::sync::atomic::Ordering;
26	use std::time::Instant;
27	
28	use super::event::FinishReason;
29	use super::event::TokenLogprob;
30	use super::request_lifecycle::DeferredFinish;
31	use super::request_lifecycle::RequestEnvelope;
32	use super::request_lifecycle::StepSender;
33	use super::step::PromptEcho;
34	use super::step::QueuedRequest;
35	use super::step::RejectReason;
36	use super::step::RequestId;
37	use super::step::RequestUpdate;
38	use super::step::ScheduledInfo;
39	use super::step::StepOutputs;
40	use super::step::Terminal;
41	use super::stop::StopCause;
42	
43	/// One open account: the request's admission facts and running tally. The
44	/// payload is not here — it went to the scheduler at `submit`; the account is
45	/// what the engine still owes the client.
46	struct Account {
47	    abort: Arc<AtomicBool>,
48	    prompt_len: usize,
49	    queued_at: Instant,
50	    state: AccountState,
51	}
52	
53	enum AccountState {
54	    /// Submitted, not yet admitted.
55	    Queued,
56	    /// Admitted; tokens tallied as they are pushed.
57	    Active { completion_tokens: usize },
58	}
59	
60	impl Account {
61	    fn completion_tokens(&self) -> usize {
62	        match self.state {
63	            AccountState::Queued => 0,
64	            AccountState::Active { completion_tokens } => completion_tokens,
65	        }
66	    }
67	}
68	
69	/// The current step's outgoing updates, merged per request so one step ships
70	/// at most one record per id.
71	#[derive(Default)]
72	struct StepStatement {
73	    buffer: Vec<Option<RequestUpdate>>,
74	    index: HashMap<RequestId, usize>,
75	}
76	
77	impl StepStatement {
78	    fn entry(&mut self, id: RequestId) -> &mut RequestUpdate {
79	        let slot = *self.index.entry(id).or_insert_with(|| {
80	            self.buffer.push(Some(RequestUpdate::empty(id)));
81	            self.buffer.len() - 1
82	        });
83	        self.buffer[slot]
84	            .as_mut()
85	            .expect("indexed step entry was extracted without index cleanup")
86	    }
87	
88	    /// Remove a request's buffered record (deferred finish, retire).
89	    fn extract(&mut self, id: RequestId) -> Option<RequestUpdate> {
90	        let slot = self.index.remove(&id)?;
91	        self.buffer[slot].take()
92	    }
93	
94	    fn take_updates(&mut self) -> Vec<RequestUpdate> {
95	        self.index.clear();
96	        self.buffer
97	            .drain(..)
98	            .flatten()
99	            .filter(|update| !update.is_vacant())
100	            .collect()
101	    }
102	}
103	
104	pub struct RequestLedger {
105	    accounts: HashMap<RequestId, Account>,
106	    statement: StepStatement,
107	    tx: StepSender,
108	}
109	
110	impl RequestLedger {
111	    pub(crate) fn new(tx: StepSender) -> Self {
112	        Self {
113	            accounts: HashMap::new(),
114	            statement: StepStatement::default(),
115	            tx,
116	        }
117	    }
118	
119	    fn account(&self, id: RequestId) -> &Account {
120	        self.accounts.get(&id).unwrap_or_else(|| {
121	            panic!("no open account for {id}: already answered, or never registered")
122	        })
123	    }
124	
125	    fn close(&mut self, id: RequestId) -> Account {
126	        self.accounts.remove(&id).unwrap_or_else(|| {
127	            panic!("no open account for {id}: already answered, or never registered")
128	        })
129	    }
130	
131	    // ── Queries ─────────────────────────────────────────────────────────
132	
133	    /// The frontend stopped wanting this request. The scheduler answers by
134	    /// [`Self::retire`] on its next touch; abort can land at any moment, so
135	    /// the probe belongs on every finish path too.
136	    pub fn is_aborted(&self, id: RequestId) -> bool {
137	        self.account(id).abort.load(Ordering::Acquire)
138	    }
139	
140	    /// Whether the account is open and admitted. For defensive paths that
141	    /// resolve effects for requests which may have been answered earlier in
142	    /// the same step (batch failure, duplicate effects).
143	    pub fn is_active(&self, id: RequestId) -> bool {
144	        matches!(
145	            self.accounts.get(&id),
146	            Some(Account {
147	                state: AccountState::Active { .. },
148	                ..
149	            })
150	        )
151	    }
152	
153	    /// Tokens shipped so far, from the ledger's tally.
154	    pub fn completion_tokens(&self, id: RequestId) -> usize {
155	        self.account(id).completion_tokens()
156	    }
157	
158	    // ── Queued-state exits ──────────────────────────────────────────────
159	
160	    /// Admit the request: stamp `scheduled_at` and buffer the admission facts.
161	    pub fn admit(&mut self, id: RequestId) {
162	        let account = self.accounts.get_mut(&id).unwrap_or_else(|| {
163	            panic!("no open account for {id}: already answered, or never registered")
164	        });
165	        assert!(
166	            matches!(account.state, AccountState::Queued),
167	            "admit on already-admitted request {id}"
168	        );
169	        account.state = AccountState::Active {
170	            completion_tokens: 0,
171	        };
172	        let scheduled = ScheduledInfo {
173	            queued_at: account.queued_at,
174	            scheduled_at: Instant::now(),
175	            prompt_tokens: account.prompt_len,
176	        };
177	        self.statement.entry(id).scheduled = Some(scheduled);
178	    }
179	
180	    /// Refuse the request at admission.
181	    pub fn reject(&mut self, id: RequestId, reason: RejectReason) {
182	        let account = self.close(id);
183	        assert!(
184	            matches!(account.state, AccountState::Queued),
185	            "reject after admission for {id}: an admitted request finishes or fails"
186	        );
187	        self.statement.entry(id).terminal = Some(Terminal::Rejected {
188	            reason,
189	            prompt_tokens: account.prompt_len,
190	        });
191	    }
192	
193	    // ── Streaming ───────────────────────────────────────────────────────
194	
195	    /// Append committed tokens. `logprobs` must be empty (none requested) or
196	    /// parallel to `ids`; the statement keeps the two aligned across pushes.
197	    pub fn push_tokens(&mut self, id: RequestId, ids: &[u32], logprobs: &[Option<TokenLogprob>]) {
198	        assert!(
199	            logprobs.is_empty() || logprobs.len() == ids.len(),
200	            "logprobs must be absent or parallel to tokens"
201	        );
202	        let account = self.accounts.get_mut(&id).unwrap_or_else(|| {
203	            panic!("no open account for {id}: already answered, or never registered")
204	        });
205	        let AccountState::Active { completion_tokens } = &mut account.state else {
206	            panic!("push_tokens on {id} before admission");
207	        };
208	        *completion_tokens += ids.len();
209	        let entry = self.statement.entry(id);
210	        entry.tokens.extend_from_slice(ids);
211	        if logprobs.is_empty() {
212	            entry.logprobs.extend(ids.iter().map(|_| None));
213	        } else {
214	            entry.logprobs.extend_from_slice(logprobs);
215	        }
216	    }
217	
218	    /// Report the prefix-cache hit count, in the step the scheduler learns it.
219	    pub fn set_cached_tokens(&mut self, id: RequestId, cached_tokens: usize) {
220	        assert!(
221	            self.is_active(id),
222	            "set_cached_tokens on {id} before admission"
223	        );
224	        self.statement.entry(id).cached_tokens = Some(cached_tokens);
225	    }
226	
227	    /// Echo the prompt back (echo mode), once, when prefill completes.
228	    pub fn echo_prompt(&mut self, id: RequestId, echo: PromptEcho) {
229	        assert!(self.is_active(id), "echo_prompt on {id} before admission");
230	        self.statement.entry(id).prompt_echo = Some(echo);
231	    }
232	
233	    /// Attach P/D handoff metadata to this step's record.
234	    pub fn kv_transfer(&mut self, id: RequestId, params: serde_json::Value) {
235	        assert!(self.is_active(id), "kv_transfer on {id} before admission");
236	        self.statement.entry(id).kv_transfer = Some(params);
237	    }
238	
239	    // ── Terminal transitions ────────────────────────────────────────────
240	
241	    /// Finish the request. Token counts come from the ledger's tally.
242	    pub fn finish(&mut self, id: RequestId, reason: FinishReason) {
243	        self.finish_with_cause(id, reason, None);
244	    }
245	
246	    /// Finish a request while preserving a typed token-level stop cause.
247	    pub fn finish_with_cause(
248	        &mut self,
249	        id: RequestId,
250	        reason: FinishReason,
251	        stop_cause: Option<StopCause>,
252	    ) {
253	        let account = self.close(id);
254	        let AccountState::Active { completion_tokens } = account.state else {
255	            panic!("finish on {id} before admission");
256	        };
257	        self.statement.entry(id).terminal = Some(Terminal::Finished {
258	            reason,
259	            stop_cause,
260	            prompt_tokens: account.prompt_len,
261	            completion_tokens,
262	        });
263	    }
264	
265	    /// Fail the request with an engine-side error. Valid in both states — a
266	    /// queued request can die to an engine error before admission.
267	    pub fn fail(&mut self, id: RequestId, message: impl Into<String>) {
268	        let account = self.close(id);
269	        self.statement.entry(id).terminal = Some(Terminal::Failed {
270	            message: message.into(),
271	            prompt_tokens: account.prompt_len,
272	            completion_tokens: account.completion_tokens(),
273	        });
274	    }
275	
276	    /// Close an aborted request's account (see [`Self::is_aborted`]). Silent,
277	    /// and discards anything buffered for it this step: the frontend already
278	    /// dropped its state for this id, so there is no one to address.
279	    pub fn retire(&mut self, id: RequestId) {
280	        let account = self.close(id);
281	        log::debug!(
282	            "request retired: frontend aborted: {id} tokens_shipped={}",
283	            account.completion_tokens()
284	        );
285	        self.statement.extract(id);
286	    }
287	
288	    /// Turn the request's finish into a token the scheduler can deliver later
289	    /// from any thread (P/D prefill roles gate `Finished` on KV-save
290	    /// visibility). Closes the account; the request's buffered update for
291	    /// this step — tokens included — folds into the returned message, so late
292	    /// delivery cannot reorder against the step stream.
293	    pub fn defer_finish(&mut self, id: RequestId, reason: FinishReason) -> DeferredFinish {
294	        self.defer_finish_with_cause(id, reason, None)
295	    }
296	
297	    /// Defer a finish while preserving a typed token-level stop cause.
298	    pub fn defer_finish_with_cause(
299	        &mut self,
300	        id: RequestId,
301	        reason: FinishReason,
302	        stop_cause: Option<StopCause>,
303	    ) -> DeferredFinish {
304	        let account = self.close(id);
305	        let AccountState::Active { completion_tokens } = account.state else {
306	            panic!("defer_finish on {id} before admission");
307	        };
308	        let mut update = self
309	            .statement
310	            .extract(id)
311	            .unwrap_or_else(|| RequestUpdate::empty(id));
312	        update.terminal = Some(Terminal::Finished {
313	            reason,
314	            stop_cause,
315	            prompt_tokens: account.prompt_len,
316	            completion_tokens,
317	        });
318	        DeferredFinish::new(update, self.tx.clone())
319	    }
320	
321	    // ── Driver face ─────────────────────────────────────────────────────
322	
323	    /// Open the account and hand back the [`QueuedRequest`] for
324	    /// [`super::Scheduler::submit`]. Consumes (and disarms) the envelope: from
325	    /// here on, the account carries the answer-on-drop duty.
326	    pub(crate) fn register(&mut self, envelope: RequestEnvelope) -> QueuedRequest {
327	        let inner = envelope.consume();
328	        let account = Account {
329	            abort: inner.abort,
330	            prompt_len: inner.request.prompt_tokens.len(),
331	            queued_at: inner.queued_at,
332	            state: AccountState::Queued,
333	        };
334	        let previous = self.accounts.insert(inner.id, account);
335	        assert!(previous.is_none(), "duplicate request id {}", inner.id);
336	        QueuedRequest {
337	            id: inner.id,
338	            request: inner.request,
339	        }
340	    }
341	
342	    /// Commit the buffered updates as described by [`StepOutputs`].
343	    pub(crate) fn commit_step(&mut self, metrics_changed: bool) {
344	        let updates = self.statement.take_updates();
345	        if updates.is_empty() && !metrics_changed {
346	            return;
347	        }
348	        // A closed receiver means the frontend is gone; the driver notices
349	        // through the submission channel and winds down.
350	        let _ = self.tx.send(StepOutputs { updates });
351	    }
352	
353	    /// Write off every open account with one message — the driver's teardown
354	    /// sweep after a fatal `step` error, carrying the real error instead of
355	    /// the drop sweep's generic one.
356	    pub(crate) fn fail_all(&mut self, message: &str) {
357	        let ids: Vec<RequestId> = self.accounts.keys().copied().collect();
358	        for id in ids {
359	            self.fail(id, message);
360	        }
361	    }
362	}
363	
364	/// The teardown sweep: accounts still open when the ledger falls are engine
365	/// bugs or teardown races, and each must surface as a finished stream instead
366	/// of a client hang.
367	impl Drop for RequestLedger {
368	    fn drop(&mut self) {
369	        if self.accounts.is_empty() {
370	            return;
371	        }
372	        let updates = self
373	            .accounts
374	            .drain()
375	            .map(|(id, account)| {
376	                let message = match account.state {
377	                    AccountState::Queued => "request dropped by the engine before it was answered",
378	                    AccountState::Active { .. } => "request dropped by the engine mid-stream",
379	                };
380	                let mut update = RequestUpdate::empty(id);
381	                update.terminal = Some(Terminal::Failed {
382	                    message: message.to_string(),
383	                    prompt_tokens: account.prompt_len,
384	                    completion_tokens: account.completion_tokens(),
385	                });
386	                update
387	            })
388	            .collect();
389	        let _ = self.tx.send(StepOutputs { updates });
390	    }
391	}
