402	
403	    fn request(prompt: Vec<u32>) -> Request {
404	        Request {
405	            prompt_tokens: prompt,
406	            params: crate::sampler::SamplingParams::default(),
407	            history_tokens: None,
408	            history_marks: Vec::new(),
409	            stop_policy: StopPolicy::default(),
410	            max_tokens: 8,
411	            lora_adapter: None,
412	            kv_transfer_params: None,
413	            logprobs: None,
414	            prompt_logprobs: None,
415	            trace_parent: None,
416	            client_label: None,
417	        }
418	    }
