420	    #[test]
421	    fn admission_tokens_and_finish_fold_into_one_entry() {
422	        let (handle, mut backend) = scheduler_pair();
423	        let _control = handle.submit(request(vec![1, 2, 3]));
424	        let envelope = backend.submissions.try_recv().expect("envelope");
425	        let id = backend.ledger.register(envelope).id;
426	
427	        backend.ledger.admit(id);
428	        backend.ledger.push_tokens(id, &[10, 11], &[]);
429	        backend.ledger.set_cached_tokens(id, 2);
430	        backend
431	            .ledger
432	            .finish_with_cause(id, FinishReason::Stop, Some(StopCause::Token(11)));
433	        backend.ledger.commit_step(false);
434	
435	        let mut steps = handle_steps(handle);
436	        let step = steps.try_recv().expect("one step message");
437	        assert_eq!(step.updates.len(), 1);
438	        let update = &step.updates[0];
439	        let scheduled = update.scheduled.as_ref().expect("admission facts");
440	        assert_eq!(scheduled.prompt_tokens, 3);
441	        assert!(scheduled.scheduled_at >= scheduled.queued_at);
442	        assert_eq!(update.tokens, vec![10, 11]);
443	        assert_eq!(update.logprobs.len(), 2);
444	        assert_eq!(update.cached_tokens, Some(2));
445	        assert!(matches!(
446	            update.terminal,
447	            Some(Terminal::Finished {
448	                reason: FinishReason::Stop,
449	                stop_cause: Some(StopCause::Token(11)),
450	                prompt_tokens: 3,
451	                completion_tokens: 2,
452	            })
453	        ));
454	        assert!(steps.try_recv().is_err());
455	    }
