457	    #[test]
458	    fn reject_carries_prompt_len_and_no_tokens() {
459	        let (handle, mut backend) = scheduler_pair();
460	        let _control = handle.submit(request(vec![1; 5]));
461	        let envelope = backend.submissions.try_recv().expect("envelope");
462	        let id = backend.ledger.register(envelope).id;
463	        backend.ledger.reject(
464	            id,
465	            RejectReason::ContextLength {
466	                prompt_tokens: 5,
467	                max_tokens: 8,
468	                limit: 4,
469	            },
470	        );
471	        backend.ledger.commit_step(false);
472	
473	        let step = handle_steps(handle).try_recv().expect("step");
474	        let update = &step.updates[0];
475	        assert!(update.scheduled.is_none());
476	        assert!(update.tokens.is_empty());
477	        assert!(matches!(
478	            &update.terminal,
479	            Some(Terminal::Rejected {
480	                reason: RejectReason::ContextLength { limit: 4, .. },
481	                prompt_tokens: 5,
482	            })
483	        ));
484	    }
