486	    #[test]
487	    fn retire_discards_buffered_output() {
488	        let (handle, mut backend) = scheduler_pair();
489	        let _control = handle.submit(request(vec![1]));
490	        let envelope = backend.submissions.try_recv().expect("envelope");
491	        let id = backend.ledger.register(envelope).id;
492	        backend.ledger.admit(id);
493	        backend.ledger.push_tokens(id, &[9], &[]);
494	        backend.ledger.retire(id);
495	        backend.ledger.commit_step(false);
496	
497	        // Scheduled was buffered before the retire extracted the entry, so
498	        // nothing observable remains this step.
499	        assert!(handle_steps(handle).try_recv().is_err());
500	    }
