502	    #[test]
503	    fn defer_finish_folds_step_output_and_delivers_late() {
504	        let (handle, mut backend) = scheduler_pair();
505	        let _control = handle.submit(request(vec![1, 2]));
506	        let envelope = backend.submissions.try_recv().expect("envelope");
507	        let id = backend.ledger.register(envelope).id;
508	        backend.ledger.admit(id);
509	        backend.ledger.push_tokens(id, &[7], &[]);
510	        let deferred = backend
511	            .ledger
512	            .defer_finish_with_cause(id, FinishReason::Length, None);
513	        backend.ledger.commit_step(false);
514	
515	        let mut steps = handle_steps(handle);
516	        // The request's whole record rode into the deferred finish; the step
517	        // itself shipped nothing.
518	        assert!(steps.try_recv().is_err());
519	
520	        std::thread::spawn(move || deferred.send())
521	            .join()
522	            .expect("deferred sender thread");
523	        let step = steps.try_recv().expect("late finish message");
524	        let update = &step.updates[0];
525	        assert!(update.scheduled.is_some());
526	        assert_eq!(update.tokens, vec![7]);
527	        assert!(matches!(
528	            update.terminal,
529	            Some(Terminal::Finished {
530	                reason: FinishReason::Length,
531	                stop_cause: None,
532	                prompt_tokens: 2,
533	                completion_tokens: 1,
534	            })
535	        ));
536	    }
