538	    #[test]
539	    fn dropped_ledger_writes_off_open_accounts() {
540	        let (handle, mut backend) = scheduler_pair();
541	        let _c0 = handle.submit(request(vec![1]));
542	        let _c1 = handle.submit(request(vec![2, 3]));
543	        let envelope = backend.submissions.try_recv().expect("envelope 0");
544	        let _queued = backend.ledger.register(envelope).id;
545	        let envelope = backend.submissions.try_recv().expect("envelope 1");
546	        let admitted = backend.ledger.register(envelope).id;
547	        backend.ledger.admit(admitted);
548	
549	        // Ledger falls with both accounts open: one queued, one active.
550	        drop(backend);
551	
552	        let mut steps = handle_steps(handle);
553	        let step = steps.try_recv().expect("write-off message");
554	        let mut prompts: Vec<usize> = step
555	            .updates
556	            .iter()
557	            .map(|update| match update.terminal {
558	                Some(Terminal::Failed { prompt_tokens, .. }) => prompt_tokens,
559	                ref other => panic!("write-off must be Failed, got {other:?}"),
560	            })
561	            .collect();
562	        prompts.sort_unstable();
563	        assert_eq!(prompts, vec![1, 2]);
564	    }
