596	    #[test]
597	    #[should_panic(expected = "no open account")]
598	    fn touching_a_closed_account_panics() {
599	        let (handle, mut backend) = scheduler_pair();
600	        let _control = handle.submit(request(vec![1]));
601	        let envelope = backend.submissions.try_recv().expect("envelope");
602	        let id = backend.ledger.register(envelope).id;
603	        backend.ledger.admit(id);
604	        backend.ledger.finish(id, FinishReason::Stop);
605	        backend.ledger.push_tokens(id, &[1], &[]);
606	    }
