1	//! Submission envelope and late-delivery handles for one request's lifetime.
2	//!
3	//! The scheduler side of the contract deals in plain [`RequestId`]s against
4	//! the [`super::RequestLedger`] — no per-request typestate handles cross the
5	//! `Scheduler` trait. What lives here are the pieces that carry a request
6	//! *outside* the ledger's reach and therefore need their own answer-on-drop
7	//! guarantee:
8	//!
9	//! - [`RequestEnvelope`] — the channel envelope between
10	//!   [`super::SchedulerHandle::submit`] and the driver's
11	//!   [`super::RequestLedger::register`]. It covers the window where the
12	//!   request exists but no ledger account does yet: sitting in the submit
13	//!   channel, or sent to a scheduler thread that already exited.
14	//! - [`DeferredFinish`] — a finish extracted from the ledger for delivery
15	//!   from another thread at a later time (P/D prefill roles withhold
16	//!   `Finished` until the step's KV saves are peer-visible).
17	//! - [`RequestControl`] — the frontend's per-request abort flag.
18	//!
19	//! The first two hold `Option<inner>` for one reason only: Rust's `Drop`
20	//! cannot move fields out, so a consuming transition `take`s the inner and
21	//! the drop bomb fires on `Some`. An unanswered request must surface as a
22	//! `Failed` terminal, never a client hang.
23	
24	use std::sync::Arc;
25	use std::sync::atomic::AtomicBool;
26	use std::sync::atomic::Ordering;
27	use std::time::Instant;
28	
29	use super::step::Request;
30	use super::step::RequestId;
31	use super::step::RequestUpdate;
32	use super::step::StepOutputs;
33	use super::step::Terminal;
34	
35	/// The scheduler-to-frontend stream: one message per step. The ledger holds
36	/// the sender; drop bombs and deferred finishes hold clones for solo sends.
37	pub(crate) type StepSender = tokio::sync::mpsc::UnboundedSender<StepOutputs>;
38	pub type StepReceiver = tokio::sync::mpsc::UnboundedReceiver<StepOutputs>;
39	
40	/// One submitted request in flight between the frontend and the driver.
41	/// Minted by [`super::SchedulerHandle::submit`]; consumed (and thereby
42	/// disarmed) by [`super::RequestLedger::register`], which opens the ledger
43	/// account that takes over the answer-on-drop duty.
44	pub(crate) struct RequestEnvelope {
45	    /// `Some` until [`Self::consume`]; `Drop` fires on `Some`.
46	    inner: Option<EnvelopeInner>,
47	}
48	
49	pub(crate) struct EnvelopeInner {
50	    pub(crate) id: RequestId,
51	    pub(crate) abort: Arc<AtomicBool>,
52	    pub(crate) tx: StepSender,
53	    pub(crate) request: Request,
54	    pub(crate) queued_at: Instant,
55	}
56	
57	impl RequestEnvelope {
58	    pub(crate) fn new(
59	        id: RequestId,
60	        abort: Arc<AtomicBool>,
61	        tx: StepSender,
62	        request: Request,
63	        queued_at: Instant,
64	    ) -> Self {
65	        Self {
66	            inner: Some(EnvelopeInner {
67	                id,
68	                abort,
69	                tx,
70	                request,
71	                queued_at,
72	            }),
73	        }
74	    }
75	
76	    pub(crate) fn consume(mut self) -> EnvelopeInner {
77	        self.inner.take().expect("submission consumed twice")
78	    }
79	}
80	
81	/// A submission dropped unconsumed never reached a ledger account: the
82	/// scheduler is gone (send failed, or the channel fell with the driver).
83	/// Answer the request so the client observes a terminal instead of a hang.
