86	        let Some(inner) = self.inner.take() else {
87	            return;
88	        };
89	        let mut update = RequestUpdate::empty(inner.id);
90	        update.terminal = Some(Terminal::Failed {
91	            message: "request dropped by the engine before it was answered".to_string(),
92	            prompt_tokens: inner.request.prompt_tokens.len(),
93	            completion_tokens: 0,
94	        });
