201	        assert!(matches!(
202	            terminal,
203	            Some(Terminal::Finished {
204	                reason: FinishReason::Length,
205	                stop_cause: None,
206	                prompt_tokens: 2,
207	                completion_tokens: 3,
208	            })
209	        ));
