1	//! Submission envelope and late-delivery handles for one request's lifetime.
2	//!
3	//! The scheduler side of the contract deals in plain [`RequestId`]s against
4	//! the [`super::RequestLedger`] — no per-request typestate handles cross the
5	//! `Scheduler` trait. What lives here are the pieces that carry a request
6	//! *outside* the ledger's reach and therefore need their own answer-on-drop
7	//! guarantee:
8	//!
9	//! - [`RequestEnvelope`] — the channel envelope between
10	//!   [`super::SchedulerHandle::submit`] and the driver's
11	//!   [`super::RequestLedger::register`]. It covers the window where the
12	//!   request exists but no ledger account does yet: sitting in the submit
13	//!   channel, or sent to a scheduler thread that already exited.
14	//! - [`DeferredFinish`] — a finish extracted from the ledger for delivery
15	//!   from another thread at a later time (P/D prefill roles withhold
16	//!   `Finished` until the step's KV saves are peer-visible).
17	//! - [`RequestControl`] — the frontend's per-request abort flag.
18	//!
19	//! The first two hold `Option<inner>` for one reason only: Rust's `Drop`
20	//! cannot move fields out, so a consuming transition `take`s the inner and
21	//! the drop bomb fires on `Some`. An unanswered request must surface as a
22	//! `Failed` terminal, never a client hang.
23	
24	use std::sync::Arc;
25	use std::sync::atomic::AtomicBool;
26	use std::sync::atomic::Ordering;
27	use std::time::Instant;
28	
29	use super::step::Request;
30	use super::step::RequestId;
31	use super::step::RequestUpdate;
32	use super::step::StepOutputs;
33	use super::step::Terminal;
34	
35	/// The scheduler-to-frontend stream: one message per step. The ledger holds
36	/// the sender; drop bombs and deferred finishes hold clones for solo sends.
37	pub(crate) type StepSender = tokio::sync::mpsc::UnboundedSender<StepOutputs>;
38	pub type StepReceiver = tokio::sync::mpsc::UnboundedReceiver<StepOutputs>;
39	
40	/// One submitted request in flight between the frontend and the driver.
41	/// Minted by [`super::SchedulerHandle::submit`]; consumed (and thereby
42	/// disarmed) by [`super::RequestLedger::register`], which opens the ledger
43	/// account that takes over the answer-on-drop duty.
44	pub(crate) struct RequestEnvelope {
45	    /// `Some` until [`Self::consume`]; `Drop` fires on `Some`.
46	    inner: Option<EnvelopeInner>,
47	}
48	
49	pub(crate) struct EnvelopeInner {
50	    pub(crate) id: RequestId,
51	    pub(crate) abort: Arc<AtomicBool>,
52	    pub(crate) tx: StepSender,
53	    pub(crate) request: Request,
54	    pub(crate) queued_at: Instant,
55	}
56	
57	impl RequestEnvelope {
58	    pub(crate) fn new(
59	        id: RequestId,
60	        abort: Arc<AtomicBool>,
61	        tx: StepSender,
62	        request: Request,
63	        queued_at: Instant,
64	    ) -> Self {
65	        Self {
66	            inner: Some(EnvelopeInner {
67	                id,
68	                abort,
69	                tx,
70	                request,
71	                queued_at,
72	            }),
73	        }
74	    }
75	
76	    pub(crate) fn consume(mut self) -> EnvelopeInner {
77	        self.inner.take().expect("submission consumed twice")
78	    }
79	}
80	
81	/// A submission dropped unconsumed never reached a ledger account: the
82	/// scheduler is gone (send failed, or the channel fell with the driver).
83	/// Answer the request so the client observes a terminal instead of a hang.
84	impl Drop for RequestEnvelope {
85	    fn drop(&mut self) {
86	        let Some(inner) = self.inner.take() else {
87	            return;
88	        };
89	        let mut update = RequestUpdate::empty(inner.id);
90	        update.terminal = Some(Terminal::Failed {
91	            message: "request dropped by the engine before it was answered".to_string(),
92	            prompt_tokens: inner.request.prompt_tokens.len(),
93	            completion_tokens: 0,
94	        });
95	        let _ = inner.tx.send(StepOutputs {
96	            updates: vec![update],
97	        });
98	    }
99	}
100	
101	/// A finish whose delivery the scheduler handed off (e.g. a P/D prefill role
102	/// withholding `Finished` until this step's KV saves are peer-visible). Made
103	/// by [`super::RequestLedger::defer_finish`], which closes the request's
104	/// ledger account and folds its already-buffered step record — tokens
105	/// included — into this message, so sending it from any thread at any later
106	/// time cannot reorder against the step stream: the whole per-request record
107	/// travels as one entry.
108	pub struct DeferredFinish {
109	    /// `Some` until [`Self::send`] delivers; `Drop` fires on `Some`.
110	    inner: Option<DeferredInner>,
111	}
112	
113	pub(crate) struct DeferredInner {
114	    pub(crate) update: RequestUpdate,
115	    pub(crate) tx: StepSender,
116	}
117	
118	impl DeferredFinish {
119	    pub(crate) fn new(update: RequestUpdate, tx: StepSender) -> Self {
120	        Self {
121	            inner: Some(DeferredInner { update, tx }),
122	        }
123	    }
124	
125	    fn inner(&self) -> &DeferredInner {
126	        self.inner
127	            .as_ref()
128	            .expect("deferred finish accessed after consumption")
129	    }
130	
131	    pub fn id(&self) -> RequestId {
132	        self.inner().update.id
133	    }
134	
135	    /// Deliver the terminal. Consumes the finish.
136	    pub fn send(mut self) {
137	        let inner = self.inner.take().expect("deferred finish sent twice");
138	        let _ = inner.tx.send(StepOutputs {
139	            updates: vec![inner.update],
140	        });
141	    }
142	}
143	
144	/// The same drop bomb as the submission envelope: an unsent deferred finish
145	/// is a holder bug, and it must surface as a finished stream, not a client
146	/// hang. The buffered tokens still ship, but the terminal is rewritten to
147	/// `Failed` — the withheld `Finished` doubles as a barrier signal (P/D
148	/// KV-ready), so a dropped handle must not fake its success.
149	impl Drop for DeferredFinish {
150	    fn drop(&mut self) {
151	        let Some(mut inner) = self.inner.take() else {
152	            return;
153	        };
154	        let (prompt_tokens, completion_tokens) = match inner.update.terminal {
155	            Some(Terminal::Finished {
156	                prompt_tokens,
157	                completion_tokens,
158	                ..
159	            }) => (prompt_tokens, completion_tokens),
160	            _ => (0, inner.update.tokens.len()),
161	        };
162	        inner.update.terminal = Some(Terminal::Failed {
163	            message: "deferred finish dropped by the engine before delivery".to_string(),
164	            prompt_tokens,
165	            completion_tokens,
166	        });
167	        let _ = inner.tx.send(StepOutputs {
168	            updates: vec![inner.update],
169	        });
170	    }
171	}
172	
173	/// The frontend's per-request cancel handle, returned by
174	/// [`super::SchedulerHandle::submit`]. Flipping the flag is the only abort
175	/// mechanism: the scheduler observes it through
176	/// [`super::RequestLedger::is_aborted`] and retires the request reactively;
177	/// no channel is closed.
178	pub struct RequestControl {
179	    id: RequestId,
180	    abort: Arc<AtomicBool>,
181	}
182	
183	impl RequestControl {
184	    pub(crate) fn new(id: RequestId, abort: Arc<AtomicBool>) -> Self {
185	        Self { id, abort }
186	    }
187	
188	    pub fn id(&self) -> RequestId {
189	        self.id
190	    }
191	
192	    /// Mark the request aborted. `Release` orders the store after the
193	    /// caller's own teardown of per-request state, mirroring the scheduler's
194	    /// `Acquire` load.
195	    pub fn abort(&self) {
196	        self.abort.store(true, Ordering::Release);
197	    }
198	}
